import java.io.*;
import java.util.*;

public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] u = new int[m];
        int[] v = new int[m];

        for (int i = 0; i < m; i++) {
            u[i] = fs.nextInt() - 1;
            v[i] = fs.nextInt() - 1;
        }

        int[][] type = new int[6][6];
        int index = 0;
        for (int a = 0; a < 6; a++) {
            for (int b = a; b < 6; b++) {
                type[a][b] = type[b][a] = index++;
            }
        }

        int assignments = 1;
        for (int i = 0; i < n; i++) assignments *= 6;

        int[] color = new int[n];
        int answer = 0;

        for (int mask = 0; mask < assignments; mask++) {
            int value = mask;
            for (int i = 0; i < n; i++) {
                color[i] = value % 6;
                value /= 6;
            }

            int usedDominoes = 0;
            for (int i = 0; i < m; i++) {
                int dominoType = type[color[u[i]]][color[v[i]]];
                usedDominoes |= 1 << dominoType;
            }

            answer = Math.max(answer, Integer.bitCount(usedDominoes));
        }

        System.out.println(answer);
    }
}

