import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] u = new int[m];
        int[] v = new int[m];

        for (int i = 0; i < m; i++) {
            u[i] = fs.nextInt() - 1;
            v[i] = fs.nextInt() - 1;
        }

        int assignments = 1;
        for (int i = 0; i < n; i++) {
            assignments *= 6;
        }

        int answer = 0;
        int[] color = new int[n];

        for (int mask = 0; mask < assignments; mask++) {
            int value = mask;
            for (int i = 0; i < n; i++) {
                color[i] = value % 6;
                value /= 6;
            }

            long usedTypes = 0;
            for (int i = 0; i < m; i++) {
                int a = color[u[i]];
                int b = color[v[i]];
                if (a > b) {
                    int temp = a;
                    a = b;
                    b = temp;
                }
                usedTypes |= 1L << (a * 6 + b);
            }

            answer = Math.max(answer, Long.bitCount(usedTypes));
        }

        System.out.println(answer);
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }
}

